evaluate(`lockPriority='gearing';constraints=[];size=6;suggestSchedule=false;confirmedOnly=false;rolePriorities=normalizeRolePriorities(undefined);fellowshipSetup=emptyFellowshipSetup();fellowshipSetup.unified=true;fellowshipSetup.slotAssignments=true;fellowshipSetup.capabilitiesSeparated=true;
var bidSlot=(role,minimum,preferred,strength,className='Any')=>({role,className,specs:[],source:'any',target:'raid',effectTarget:className==='Any'?'all':'same',minimum,preferred,strength,...(className==='Any'?{}:{requirementKind:'presence'})});
var bidPlayer=(id,choices,extra={},count=2)=>({id,name:id,max:1,available:Array(count).fill(true),choices,...extra});
var bidC={mini:{c:'Minstrel',spec:'Blue',role:'Healer'},hunt:{c:'Hunter',spec:'Red',role:'DPS'},champ:{c:'Champion',spec:'Red',role:'DPS'},rk:{c:'Rune-keeper',spec:'Blue',role:'Healer'},guard:{c:'Guardian',spec:'Blue',role:'Tank'},burg:{c:'Burglar',spec:'Red',role:'DPS'},lm:{c:'Lore-master',spec:'Red',role:'DPS'},war:{c:'Warden',spec:'Red',role:'DPS'},bear:{c:'Beorning',spec:'Red',role:'DPS'}};
var bidRuns=n=>Array.from({length:n},(_,i)=>({id:i+1,source:i,time:18+2*i,label:'Run '+(i+1)}));
var miniCounts=()=>teams.map(t=>t.members.filter(m=>m.c==='Minstrel').length).join(',');
fellowshipSetup.rules=[bidSlot('Healer',1,1,'hard'),bidSlot('Healer',0,1,'soft'),bidSlot('Tank',1,1,'hard'),bidSlot('Any',0,1,'soft','Minstrel')];runs=bidRuns(2);
players=[bidPlayer('starMini',[bidC.mini,bidC.hunt],{preferredClasses:['Minstrel']}),bidPlayer('mini2',[bidC.mini,bidC.champ]),bidPlayer('rk1',[bidC.rk,bidC.lm]),bidPlayer('t1',[bidC.guard]),bidPlayer('t2',[bidC.guard]),...['hunt','champ','burg','lm','war','bear','hunt'].map((c,i)=>bidPlayer('d'+i,[bidC[c]]))];
syncUnifiedRoles();teams=assignCore(runs,false);`);
