players=[bidPlayer('mA',[bidC.mini]),bidPlayer('mB',[bidC.mini]),{...bidPlayer('rA',[bidC.rk]),available:[false,true]},{...bidPlayer('rB',[bidC.rk]),available:[false,true]},bidPlayer('t1',[bidC.guard]),bidPlayer('t2',[bidC.guard]),...['hunt','champ','burg','lm','war','bear'].map((c,i)=>bidPlayer('d'+i,[bidC[c]]))];
