// Regression: preserve balancing candidates outside the normal cheap shortlist.
evaluate(`size=12;players=Array.from({length:12},(_,i)=>({id:'short'+i,name:'S'+i,available:[true],choices:[{c:'Hunter',spec:'Red',role:'DPS'}],...(i<6?{inexperiencedClasses:['Hunter']}:{experiencedClasses:['Hunter']})}));let shortlistMembers=players.map(p=>({...p,...p.choices[0]}));let unbalanced=[{id:1,time:18,members:shortlistMembers.slice(0,6)},{id:2,time:18,members:shortlistMembers.slice(6)}];let even=[{id:1,time:18,members:shortlistMembers.slice(0,3).concat(shortlistMembers.slice(6,9))},{id:2,time:18,members:shortlistMembers.slice(3,6).concat(shortlistMembers.slice(9))}];let shortlistProposals=Array.from({length:60},(_,i)=>({next:unbalanced,hardApprox:0,severeConstraintApprox:0,constraintApprox:0,repeatPenalty:0,cheap:i}));let experienceProposal={next:even,hardApprox:0,severeConstraintApprox:0,constraintApprox:0,repeatPenalty:0,cheap:1000};shortlistProposals.push(experienceProposal);`);
assert(evaluate('repairShortlist(shortlistProposals).includes(experienceProposal)'));
assert(evaluate('repairShortlist(shortlistProposals).length<=48'));
